    if (order.amountCents < coupon.minAmountCents) {
      throw badRequest("COUPON_MIN_AMOUNT", `order amount is below coupon ${code} minimum`);
    }

    const raw = coupon.type === "FIXED" ? coupon.value : Math.round((order.amountCents * coupon.value) / 100);
    const capped = coupon.maxDiscountCents === null ? raw : Math.min(raw, coupon.maxDiscountCents);
